// Simulator-only boot service and explicitly virtual radio environment.
// Native firmware, SRAM/FIFOs and peripherals remain owned by the CPU engine.
export class PicoServices{
 constructor(runtime){this.r=runtime;this.stack=0;this.core1=false;this.radio={initialized:false,station:false,link:0,led:false,rx:[],tx:0,received:0};this.args=new Map();this.network={ssid:'WirevoLab',password:'wirevo1234',enabled:true};}
 configureNetwork(config={}){if(typeof config.ssid!=='string'||config.ssid.length>32||typeof config.password!=='string'||config.password.length>63)throw Error('Sanal AP ayarları geçersiz.');this.network={ssid:config.ssid,password:config.password,enabled:config.enabled!==false};this.radio.link=0;this.radio.rx=[];delete this.radio.joinAt;delete this.radio.ipAt;}
 tick(){const n=this.radio,now=this.r.rp.clock.nanos;if(n.link>=2&&(!this.network.enabled||n.ssid!==this.network.ssid)){n.link=-2;n.rx=[];delete n.ipAt;}if(n.joinAt!==undefined&&now>=n.joinAt){delete n.joinAt;if(!this.network.enabled||n.ssid!==this.network.ssid)n.link=-2;else if(n.password!==this.network.password||n.auth!==(this.network.password?0x00400004:0))n.link=-3;else{n.link=2;n.ipAt=now+1000000;}}if(n.ipAt!==undefined&&now>=n.ipAt){delete n.ipAt;if(n.link===2)n.link=3;}}
 safe(address,length){const a=address>>>0,r=this.r;if(!Number.isInteger(length)||length<0||length>512||!(a>=0x20000000&&a+length<=0x20000000+r.board.ram||a>=0x10000000&&a+length<=0x10000000+r.image.length))throw Error('Pico servis tamponu RAM/Flash dışında.');return a;}
 bleCommand({action,text=''}){if(!this.r.board.wireless)throw Error('Bu kartta radyo yok.');const b=this.ble;if(action==='connect'){if(!b?.advertising)throw Error('Firmware henüz BLE reklamı başlatmadı.');b.connected=true;}else if(action==='disconnect'){if(b){b.connected=false;b.rx=[];}}else if(action==='send'){if(!b?.connected)throw Error('Önce sanal BLE bağlantısı kurun.');const bytes=new TextEncoder().encode(text);if(bytes.length>512||b.rx.length>=8)throw Error('Sanal BLE tampon sınırı.');b.rx.push(bytes);}else throw Error('Sanal BLE komutu geçersiz.');}
 bleNative(command){this.result=-1;if(command===7){if(!this.radio.initialized)return;this.ble={advertising:true,connected:false,name:this.string(this.args.get(0x108),32),rx:[],received:[]};this.result=0;return;}const b=this.ble;if(!b?.connected)return;const len=this.args.get(0x124),ptr=this.args.get(0x120);if(command===8){const data=this.bytes(ptr,len);b.received.push(...data);b.received=b.received.slice(-1024);this.result=len;}else if(command===9){this.result=0;const data=b.rx[0];if(!data)return;const n=Math.min(len,data.length),a=this.safe(ptr,n);if(a<0x20000000)throw Error('BLE alım tamponu RAM olmalı.');for(let i=0;i<n;i++)this.r.rp.writeUint8(a+i,data[i]);if(n===data.length)b.rx.shift();else b.rx[0]=data.slice(n);this.result=n;}}
 bytes(address,length){const a=this.safe(address,length);return Uint8Array.from({length},(_,i)=>this.r.rp.readUint8(a+i));}
 string(address,max=64){const bytes=[];for(let i=0;i<=max;i++){const c=this.bytes(address+i,1)[0];if(!c)return new TextDecoder().decode(Uint8Array.from(bytes));bytes.push(c);}throw Error('Pico servis metni çok uzun.');}
 launch(entry){const r=this.r;if(!entry){this.core1=false;r.rp.core[1].reset();return;}if(this.core1)throw Error('Core 1 önce multicore_reset_core1 ile sıfırlanmalı.');if(!(entry&1)||(entry&~1)<0x10000000||(entry&~1)>=0x10000000+r.image.length||this.stack<0x20000008||this.stack>0x20000000+r.board.ram||(this.stack&7))throw Error('Core 1 giriş/stack adresi geçersiz.');const c=r.rp.core[1];c.reset();c.cycles=r.core.cycles;if(r.board.mcu==='RP2350'){c.regs.sp=this.stack;c.regs.msp=this.stack;}else c.SP=this.stack;c.PC=entry&~1;r.rp.currentCore=1;r.rp.writeUint32(0xe000ed08,0x10000000);r.rp.currentCore=0;this.core1=true;}
 read(address){const o=(address>>>0)-0x5fffe000;if(o<0||o>0x1ff)return null;this.tick();if(o===4)return this.stack;if(o===8)return +this.core1;if(o===0x104)return this.radio.link>>>0;if(o===0x114)return +(this.r.cyw43?.led??this.radio.led);if(o===0x128)return this.result>>>0;if(o===0x130)return this.radio.link>=2?(-42>>>0):0;if(o===0x134)return 0x43565702;if(o===0x138)return (this.r.board.mcu==='RP2350'?0x23:0x20)|(this.r.board.headers?0x100:0);if(o===0x13c)return this.r.cyw43?.gpioInput??0;if(o===0x12c)return +!!this.ble?.connected;return this.args.get(o)||0;}
 write(address,value){const o=(address>>>0)-0x5fffe000;if(o<0||o>0x1ff)return false;value>>>=0;if(o===4)this.stack=value;else if(o===8)this.launch(value);else if(o>=0x100){if(!this.r.board.wireless)throw Error('Bu Pico kartında dahili radyo yok.');if(o===0x114){if(this.r.cyw43)this.r.cyw43.setLED(value);else this.radio.led=!!value;}else if(o===0x140)this.r.cyw43?.setGPIO(value>>>1,value&1);else if(o===0x100)this.command(value);else this.args.set(o,value);}return true;}
 command(command){if(command>=7&&command<=9){this.bleNative(command);return;}const n=this.radio;if(command===10||command===11){if(command===11)n.station=false;delete n.joinAt;delete n.ipAt;n.link=0;n.rx=[];return;}if(command===0){this.r.cyw43?.power(false);n.initialized=n.station=false;n.link=0;n.rx=[];n.led=false;this.ble=null;delete n.joinAt;delete n.ipAt;}else if(command===1){this.r.cyw43?.power(true);n.initialized=true;n.link=0;}else if(command===2){n.station=n.initialized;}else if(command===3){n.link=-1;if(n.station){n.ssid=this.string(this.args.get(0x108),32);n.password=this.args.get(0x10c)?this.string(this.args.get(0x10c),63):'';n.auth=this.args.get(0x110);n.link=1;n.joinAt=this.r.rp.clock.nanos+1000000;}}else if(command===4){delete n.joinAt;n.link=-1;}else if(command===5){const len=this.args.get(0x124);this.result=-1;if(n.link===3&&len<=512&&n.rx.length<8&&this.string(this.args.get(0x118),15)==='192.168.4.1'&&this.args.get(0x11c)===7){n.rx.push(this.bytes(this.args.get(0x120),len));n.tx++;this.result=len;}}else if(command===6){this.result=0;if(n.link!==3){this.result=-1;return;}if(n.rx.length){const data=n.rx[0],len=Math.min(data.length,this.args.get(0x124)),ptr=this.safe(this.args.get(0x120),len);if(ptr<0x20000000)throw Error('Ağ alım tamponu yazılabilir RAM olmalı.');for(let i=0;i<len;i++)this.r.rp.writeUint8(ptr+i,data[i]);if(len===data.length)n.rx.shift();else n.rx[0]=data.slice(len);n.received+=len;this.result=len;}}}
 snapshot(){this.tick();return{environment:{...this.r.environment,adcError:this.r.lastADCError},onboardLED:this.r.board.wireless?(this.r.cyw43?.led??this.radio.led):this.r.rp.gpio[25].value===1,core1Running:this.core1,cores:this.r.rp.core.map((c,i)=>({id:i,running:i===0||this.core1,cycles:c.cycles,pc:c.PC})),usb:this.r.usbHost.snapshot(),radio:{available:this.r.board.wireless,chip:this.r.cyw43?.snapshot()??null,model:'Virtual AP / UDP echo; no Internet',ssid:this.network.ssid,enabled:this.network.enabled,link:this.radio.link,led:this.radio.led,txPackets:this.radio.tx,receivedBytes:this.radio.received,ble:this.ble?{advertising:this.ble.advertising,connected:this.ble.connected,name:this.ble.name,received:new TextDecoder().decode(Uint8Array.from(this.ble.received))}:null}};}
}
